Topshiriq:

MATLAB ga ikki o'lchamli signalni import qilish, unga morfologik ishlov berish:

%% Tasvirni yuklash

I = imread('D:/mother.tif');

Igray = rgb2gray(I);

BW = imbinarize(Igray);

%% Struktur element yaratish

SE = strel('disk', 5);   % 5 radiusli disk

%% Morfologik amallar

I_erode    = imerode(BW, SE);        % Eroziya

I_dilate   = imdilate(BW, SE);       % Dilyatsiya

I_open     = imopen(BW, SE);         % Opening

I_close    = imclose(BW, SE);        % Closing

I_contour  = BW - imerode(BW, SE);   % Kontur olish

I_tophat   = imtophat(Igray, SE);    % Top-hat (grayscale)

I_blackhat = imbothat(Igray, SE);    % Black-hat (grayscale)

I_grad     = imdilate(BW,SE) - imerode(BW,SE);  % Morfologik gradient

%% Barcha natijalarni bitta oynada chiqarish

figure('Name','Morfologik amallar natijalari','NumberTitle','off');

imshow(I); title('Original rasm');

imshow(Igray); title('Original rasm');

imshow(BW); title('Ikkilik tasvir');

imshow(I_erode); title('Eroziya');

imshow(I_dilate); title('Dilyatsiya');

imshow(I_open); title('Opening');

imshow(I_close); title('Closing');

imshow(I_contour); title('Kontur');

imshow(I_grad); title('Morfologik Gradient');

imshowpair(I_tophat, I_blackhat, 'montage');

title('Top-hat & Black-hat');

